<template>
  <section class="workspace-panel">
    <div class="section-heading"><div><h2>Profile V2</h2><p>画像只汇总通过准入门控的证据。数值缺失不会补零。</p></div><button class="secondary-button" @click="confirmOpen=true">重建 Profile</button></div>
    <AsyncState :loading="loading" :error="error" :empty="!snapshot" empty-title="尚无 Profile V2" empty-text="可在确认后显式重建；页面不会自动触发。" @retry="load">
      <div v-if="snapshot" class="summary-strip"><div><small>版本</small><strong>{{ snapshot.profile_schema_version }}</strong></div><div><small>状态</small><StatusBadge :status="snapshot.status" /></div><div><small>生成时间</small><strong>{{ formatDateTime(snapshot.generated_at) }}</strong></div><div><small>证据截止</small><strong>{{ formatDateTime(snapshot.as_of) }}</strong></div></div>
      <div class="dimension-grid professional"><button v-for="d in dimensions" :key="String(d.code)" class="dimension-card selectable" @click="selectedDimension=String(d.code)"><div><h3>{{ d.code }}</h3><StatusBadge :status="String(d.status||'insufficient_evidence')" /></div><JsonDetails :value="d" /></button></div>
      <article v-if="selectedEvidence.length" class="surface-card"><h3>{{ selectedDimension }} · 证据链</h3><div class="timeline"><article v-for="item in selectedEvidence" :key="item.id"><span></span><div><strong>{{ item.source_kind }} · {{ item.source_dimension_code }}</strong><p>{{ formatDateTime(item.evidence_timestamp) }} · {{ item.unit||'单位未提供' }} · {{ item.canonical_result_status }}</p><small>{{ item.source_type }} / {{ item.metric_status||'无 metric 状态' }}</small></div></article></div></article>
      <article class="surface-card"><h3>历史快照</h3><div class="timeline"><article v-for="item in history" :key="item.id"><span></span><div><strong>{{ item.profile_schema_version }} · {{ item.status }}</strong><p>{{ formatDateTime(item.generated_at) }} · 截止 {{ formatDateTime(item.as_of) }}</p><small>{{ dimensionCount(item) }} 个维度</small></div></article></div></article>
    </AsyncState>
    <ConfirmDialog :open="confirmOpen" title="重建患者画像？" message="系统将基于当前可采纳证据生成一个新的不可变快照。旧快照仍会保留。" confirm-label="确认重建" :busy="rebuilding" @cancel="confirmOpen=false" @confirm="rebuild" />
  </section>
</template>
<script setup lang="ts">
import { computed,onMounted,ref } from 'vue'; import { profileV2Api } from '@/api/profileV2'; import AsyncState from '@/components/common/AsyncState.vue'; import ConfirmDialog from '@/components/common/ConfirmDialog.vue'; import JsonDetails from '@/components/common/JsonDetails.vue'; import StatusBadge from '@/components/common/StatusBadge.vue'; import { formatDateTime } from '@/utils/date'; import type { JsonObject,ProfileEvidence,ProfileSnapshot } from '@/types/professional'
const props=defineProps<{patientId:string}>(); const snapshot=ref<ProfileSnapshot|null>(null),history=ref<ProfileSnapshot[]>([]),evidence=ref<ProfileEvidence[]>([]),loading=ref(true),error=ref(''),selectedDimension=ref(''),confirmOpen=ref(false),rebuilding=ref(false)
const dimensions=computed<JsonObject[]>(()=>{const raw=snapshot.value?.payload.dimensions;return Array.isArray(raw)?raw.filter((v):v is JsonObject=>Boolean(v)&&typeof v==='object'&&!Array.isArray(v)):[]}); const selectedEvidence=computed(()=>evidence.value.filter(x=>!selectedDimension.value||x.profile_dimension_code===selectedDimension.value))
async function load(){loading.value=true;error.value='';try{snapshot.value=await profileV2Api.latest(props.patientId);[history.value,evidence.value]=await Promise.all([profileV2Api.history(props.patientId),profileV2Api.evidence(props.patientId,snapshot.value.id)])}catch(e){error.value=e instanceof Error?e.message:'加载失败'}finally{loading.value=false}}
async function rebuild(){rebuilding.value=true;error.value='';try{await profileV2Api.rebuild(props.patientId);confirmOpen.value=false;await load()}catch(e){error.value=e instanceof Error?e.message:'重建失败'}finally{rebuilding.value=false}} function dimensionCount(item:ProfileSnapshot){return Array.isArray(item.payload.dimensions)?item.payload.dimensions.length:0} onMounted(load)
</script>
